<template>
<div class="road-page"><Sidebar/><main class="road-main">
  <header class="road-top"><label>⌕ <input v-model="search" placeholder="Araç, plaka, model, talep no..." /></label><span>{{customerName}} · Filo Yöneticisi</span></header>
  <div class="road-content">
    <header class="heading"><div><h1>♧ Yol Yardım</h1><p>Araçlarınızın yol yardım taleplerini görüntüleyin, takip edin ve hızlıca çözüm sağlayın.</p></div><button class="primary" @click="openCreate">＋ Yol Yardım Talebi</button></header>
    <section class="metrics">
        <article><i>🚙</i><small>Toplam Talep</small><b>{{cases.length}}</b></article><article class="red"><i>!</i><small>Devam Eden</small><b>{{activeCount}}</b></article><article class="green"><i>✓</i><small>Tamamlanan</small><b>{{resolvedCount}}</b></article><article><i>◷</i><small>Ortalama Yanıt Süresi</small><b>{{averageResponse==='—'?'—':averageResponse+' dk'}}</b></article><article class="last-week" @click="lastSevenDays=!lastSevenDays"><i>▣</i><small>Son 7 Gün</small><b>{{lastWeekCount}}</b></article>
    </section>
    <div class="columns">
      <section class="list-col">
        <div class="filters"><label class="find">⌕ <input v-model="search" placeholder="Plaka, marka, model, talep no ara..." /></label><label><small>Araç Grubu</small><select v-model="groupFilter"><option value="all">Tümü</option><option v-for="g in groups" :key="g">{{g}}</option></select></label><label><small>Durum</small><select v-model="statusFilter"><option value="all">Tümü</option><option v-for="s in statuses" :key="s">{{s}}</option></select></label><label><small>Tarih</small><input v-model="fromDate" type="date"/></label><button @click="page=1">⚲ Filtrele</button></div>
        <nav class="tabs"><button v-for="t in tabs" :key="t.key" :class="{active:activeTab===t.key}" @click="activeTab=t.key">{{t.label}} <b>{{tabCount(t.key)}}</b></button></nav>
        <section class="panel"><header><b>♧ Yol Yardım Talepleri</b><button class="export" @click="exportCsv">↓ Dışa Aktar</button></header><div class="scroll"><table><thead><tr><th>Talep No</th><th>Tarih / Saat</th><th>Araç / Plaka</th><th>Konum</th><th>Arıza Nedeni</th><th>Durum</th><th>Gelişat</th><th></th></tr></thead><tbody>
          <tr v-for="c in paginated" :key="c.id" :class="{selected:selected?.id===c.id}" @click="selectCase(c)"><td class="case-no">{{c.case_no}}</td><td>{{dateTime(c.created_at)}}</td><td><div class="vehicle-row">🚙 <span>{{c.vehicle_brand}} {{c.vehicle_model}}<b>{{c.plate}}</b></span></div></td><td class="loc">{{c.location||'Konum paylaşılmadı'}}</td><td>{{c.incident}}</td><td><span class="status" :class="statusClass(c.status)">{{c.status}}</span></td><td><small>%{{c.progress}}</small><div class="bar"><i :style="{width:c.progress+'%'}"></i></div></td><td><button class="dots" @click.stop="selectCase(c)">•••</button></td></tr>
          <tr v-if="!paginated.length"><td colspan="8" class="empty">Yol yardım talebi bulunamadı.<button @click="openCreate">＋ Yeni Talep Oluştur</button></td></tr>
        </tbody></table></div><footer>Toplam {{filtered.length}} talep, {{start}}–{{end}} görüntüleniyor <span><button :disabled="page<=1" @click="page--">‹</button> {{page}} / {{pages}} <button :disabled="page>=pages" @click="page++">›</button></span></footer></section>
      </section>
      <aside class="details-col">
        <section class="panel detail"><header><b>♧ Talep Detayı</b><span v-if="selected" class="status" :class="statusClass(selected.status)">{{selected.status}}</span></header>
          <template v-if="selected"><div class="vehicle-info"><div class="car-img">🚙</div><b>{{selected.vehicle_brand}} {{selected.vehicle_model}}</b><strong>{{selected.plate}}</strong><dl><dt>Marka / Model</dt><dd>{{selected.vehicle_brand}} / {{selected.vehicle_model}}</dd><dt>Şasi No</dt><dd>{{selected.chassis_no||'—'}}</dd><dt>Motor No</dt><dd>{{selected.engine_no||'—'}}</dd><dt>Renk</dt><dd>{{selected.color||'—'}}</dd><dt>Yıl</dt><dd>{{selected.vehicle_year||'—'}}</dd><dt>Kira Başlangıç</dt><dd>{{date(selected.contract_start_date)}}</dd><dt>Kira Bitiş</dt><dd>{{date(selected.contract_end_date)}}</dd></dl></div>
            <div v-if="mapSrc" class="map"><iframe :src="mapSrc" title="Talep konumu" loading="lazy"></iframe><a :href="mapLink" target="_blank" rel="noreferrer">Haritada Aç ↗</a></div><div v-else class="map-empty">⌖ <b>Konum bilgisi paylaşılmadı</b></div>
            <div class="request-info"><h3>Talep Bilgileri</h3><dl><dt>Talep No</dt><dd>{{selected.case_no}}</dd><dt>Tarih / Saat</dt><dd>{{dateTime(selected.created_at)}}</dd><dt>Arıza Nedeni</dt><dd>{{selected.incident}}</dd><dt>Konum</dt><dd>{{selected.location||'—'}}</dd><dt>Açıklama</dt><dd>{{selected.description||'—'}}</dd><dt>Yardım Ekibi</dt><dd>{{selected.team_name||'Atama bekleniyor'}}</dd><dt>Tahmini Varış</dt><dd>{{selected.eta_minutes==null?'—':selected.eta_minutes+' dk'}}</dd></dl><div class="actions"><button class="primary" @click="shareLocation">⌖ Konumumu Paylaş</button><a v-if="selected.team_phone" :href="'tel:'+selected.team_phone">☎ Ekibi Ara</a><button v-else @click="supportContact">☎ Destek İste</button></div></div>
          </template><p v-else class="empty-note">Detayları görmek için listeden talep seçin.</p>
        </section>
        <section class="panel timeline"><header><b>♧ Yol Yardım Süreci</b><button v-if="selected" @click="loadEvents(selected)">↻</button></header><ol v-if="events.length"><li v-for="e in events" :key="e.id"><i>{{e.status==='Çözüldü'?'✓':'•'}}</i><div><b>{{e.title}}</b><small>{{dateTime(e.created_at)}}</small><p>{{e.description||''}}</p><small v-if="e.eta_minutes">{{e.eta_minutes}} dk · {{e.distance_km||0}} km</small></div></li></ol><p v-else class="empty-note">Henüz süreç hareketi yok.</p></section>
      </aside>
    </div>
  </div>
</main>
<div v-if="modal" class="overlay" @click.self="modal=false"><section class="dialog"><header><div><small>FLEETRENT · YOL YARDIM</small><h2>Yeni Yol Yardım Talebi</h2></div><button @click="modal=false">×</button></header><form @submit.prevent="createCase"><div class="form-grid"><label>Araç<select v-model="form.vehicle_id" required><option value="" disabled>Araç seçin</option><option v-for="v in vehicles" :key="v.id" :value="v.id">{{v.plate}} · {{v.brand}} {{v.model}}</option></select></label><label>Arıza / İhtiyaç<select v-model="form.incident"><option>Kaza</option><option>Lastik patladı</option><option>Arıza</option><option>Akü bitti</option><option>Marş basmıyor</option><option>Yakıt bitti</option><option>Elektrik arızası</option><option>Kilit arızası</option><option>Diğer</option></select></label><label>Konum / Adres<input v-model.trim="form.location" placeholder="İl, ilçe, yol veya açık adres"/></label><label>Enlem (isteğe bağlı)<input v-model.number="form.latitude" type="number" step="any"/></label><label>Boylam (isteğe bağlı)<input v-model.number="form.longitude" type="number" step="any"/></label></div><label>Açıklama<textarea v-model.trim="form.description" rows="3" placeholder="Durumu ve ihtiyacınızı açıklayın"/></label><p v-if="error" class="error">{{error}}</p><footer><button type="button" class="cancel" @click="modal=false">Vazgeç</button><button class="primary" :disabled="saving">{{saving?'Gönderiliyor…':'Yardım Talebi Oluştur'}}</button></footer><small class="privacy">Konum yalnızca bu yol yardım talebi için saklanır.</small></form></section></div>
</div>
</template>

<script setup>
import {ref,reactive,computed,onMounted,watch} from 'vue'
import Sidebar from '../components/Sidebar.vue'
const customerId=localStorage.getItem('fleetcar_customer_id'),customerName=localStorage.getItem('fleetcar_customer_name')||'Filo Yöneticisi'
const cases=ref([]),vehicles=ref([]),events=ref([]),selected=ref(null),search=ref(''),groupFilter=ref('all'),statusFilter=ref('all'),fromDate=ref(''),activeTab=ref('all'),lastSevenDays=ref(false),page=ref(1),modal=ref(false),saving=ref(false),error=ref('')
const statuses=['Beklemede','Ekip Atandı','Yola Çıktı','Yolda','Ekip Varış Noktasında','Çözüldü','İptal Edildi'],tabs=[{key:'all',label:'Tümü'},{key:'Beklemede',label:'Beklemede'},{key:'moving',label:'Yolda'},{key:'Çözüldü',label:'Çözüldü'},{key:'İptal Edildi',label:'İptal Edildi'}]
const form=reactive({vehicle_id:'',incident:'Kaza',location:'',latitude:null,longitude:null,description:''})
const groups=computed(()=>[...new Set(vehicles.value.map(v=>v.vehicle_segment||v.vehicle_type).filter(Boolean))].sort())
const activeCount=computed(()=>cases.value.filter(c=>!['Çözüldü','İptal Edildi'].includes(c.status)).length),resolvedCount=computed(()=>cases.value.filter(c=>c.status==='Çözüldü').length)
const lastWeekCount=computed(()=>cases.value.filter(c=>new Date(c.created_at).getTime()>=Date.now()-7*86400000).length)
const averageResponse=computed(()=>{const a=cases.value.map(c=>c.response_minutes).filter(v=>v!=null);return a.length?Math.round(a.reduce((x,y)=>x+Number(y),0)/a.length):'—'})
const filtered=computed(()=>cases.value.filter(c=>{const q=search.value.trim().toLocaleLowerCase('tr-TR'),txt=[c.case_no,c.plate,c.vehicle_brand,c.vehicle_model,c.incident,c.location,c.description].join(' ').toLocaleLowerCase('tr-TR'),v=vehicles.value.find(x=>String(x.id)===String(c.vehicle_id)),group=v?.vehicle_segment||v?.vehicle_type,day=String(c.created_at||'').slice(0,10);return(!q||txt.includes(q))&&(groupFilter.value==='all'||group===groupFilter.value)&&(statusFilter.value==='all'||c.status===statusFilter.value)&&(!fromDate.value||day>=fromDate.value)&&(!lastSevenDays||new Date(c.created_at).getTime()>=Date.now()-7*86400000)&&tabMatches(activeTab.value,c.status)}).sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at))))
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/10))),paginated=computed(()=>filtered.value.slice((page.value-1)*10,page.value*10)),start=computed(()=>filtered.value.length?(page.value-1)*10+1:0),end=computed(()=>Math.min(page.value*10,filtered.value.length))
const tabCount=k=>k==='all'?cases.value.length:k==='moving'?cases.value.filter(c=>['Ekip Atandı','Yola Çıktı','Yolda','Ekip Varış Noktasında'].includes(c.status)).length:cases.value.filter(c=>c.status===k).length
function tabMatches(tab,status){return tab==='all'||(tab==='moving'?['Ekip Atandı','Yola Çıktı','Yolda','Ekip Varış Noktasında'].includes(status):status===tab)}
const mapSrc=computed(()=>{const c=selected.value;if(c?.latitude==null||c?.longitude==null)return'';const a=Number(c.latitude),o=Number(c.longitude),p=.02;return'https://www.openstreetmap.org/export/embed.html?bbox='+(o-p)+'%2C'+(a-p)+'%2C'+(o+p)+'%2C'+(a+p)+'&layer=mapnik&marker='+a+'%2C'+o})
const mapLink=computed(()=>selected.value?.latitude==null?'#':'https://www.openstreetmap.org/?mlat='+selected.value.latitude+'&mlon='+selected.value.longitude+'#map=15/'+selected.value.latitude+'/'+selected.value.longitude)
watch([search,groupFilter,statusFilter,fromDate,activeTab,lastSevenDays],()=>page.value=1)
function statusClass(s){return({'Beklemede':'pending','Ekip Atandı':'assigned','Yola Çıktı':'moving','Yolda':'moving','Ekip Varış Noktasında':'moving','Çözüldü':'resolved','İptal Edildi':'cancelled'})[s]||'pending'}
function date(v){if(!v)return'—';const d=new Date(v);return Number.isNaN(d.getTime())?v:d.toLocaleDateString('tr-TR')}
function dateTime(v){if(!v)return'—';const d=new Date(v);return Number.isNaN(d.getTime())?v:d.toLocaleString('tr-TR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}
async function load(){if(!customerId){cases.value=[];vehicles.value=[];selected.value=null;return}const s='?customer_id='+encodeURIComponent(customerId), [a,b]=await Promise.all([fetch('/api/roadside-cases'+s),fetch('/api/vehicles'+s)]);if(a.ok)cases.value=await a.json();if(b.ok)vehicles.value=await b.json();if(!selected.value&&cases.value.length)await selectCase(cases.value[0])}
async function selectCase(c){selected.value=c;await loadEvents(c)}
async function loadEvents(c){const r=await fetch('/api/roadside-cases/'+c.id+'/events');events.value=r.ok?await r.json():[]}
function openCreate(){Object.assign(form,{vehicle_id:vehicles.value[0]?.id||'',incident:'Kaza',location:'',latitude:null,longitude:null,description:''});error.value='';modal.value=true}
async function createCase(){saving.value=true;error.value='';const r=await fetch('/api/roadside-cases',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form)}).catch(()=>null);saving.value=false;if(!r?.ok){error.value='Talep kaydedilemedi. Araç ve koordinat bilgilerini kontrol edin.';return}const c=await r.json();modal.value=false;await load();const item=cases.value.find(x=>x.id===c.id);if(item)await selectCase(item)}
async function shareLocation(){if(!selected.value)return;if(!navigator.geolocation){error.value='Tarayıcı konum paylaşımını desteklemiyor.';return}navigator.geolocation.getCurrentPosition(async p=>{const c=selected.value,r=await fetch('/api/roadside-cases/'+c.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({latitude:p.coords.latitude,longitude:p.coords.longitude,location:c.location||'Müşteri konum paylaşımı'})});if(r.ok){selected.value=await r.json();await loadEvents(selected.value);await load()}else error.value='Konum kaydedilemedi.'},()=>{error.value='Konum izni alınamadı. Adresi talep açıklamasına ekleyebilirsiniz.'},{enableHighAccuracy:true,timeout:10000})}
function supportContact(){if(selected.value)location.href='/dashboard/requests?type=yol_yardim&vehicle_id='+encodeURIComponent(selected.value.vehicle_id)}
function exportCsv(){const h=['Talep No','Tarih','Plaka','Araç','Konum','Arıza Nedeni','Durum','Gelişat'],rows=filtered.value.map(c=>[c.case_no,c.created_at,c.plate,(c.vehicle_brand||'')+' '+(c.vehicle_model||''),c.location,c.incident,c.status,c.progress+'%']),csv=[h,...rows].map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(';')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'}));a.download='fleetrent-yol-yardim.csv';a.click();URL.revokeObjectURL(a.href)}
onMounted(load)
</script>

